  const st = [];
  for (let i = 0; i < a.length; i++) {
    while (st.length && a[i] > a[st.at(-1)]) res[st.pop()] = a[i];
    st.push(i);
  }
  return res;
}

function balanced(s) {
  const pairs = { ')': '(', ']': '[', '}': '{' };
  const st = [];
  for (const c of s) {
    if (c in pairs) { if (st.pop() !== pairs[c]) return false; }
    else st.push(c);
  }
  return st.length === 0;
}
