function insertionSort(a) {
  let shifts = 0;
  for (let i = 1; i < a.length; i++) {
    const x = a[i];
    let j = i - 1;
    while (j >= 0 && a[j] > x) { a[j + 1] = a[j]; j--; shifts++; }
    a[j + 1] = x;
  }
  return shifts;
}
